// ***************
// Filename: intc_top.sv
// Author: FPGA Cores 4 U
// Description: intc with its AXI4-Lite register interface, the block designs
//   and testbenches instantiate: the register map intc_regs (u_regs,
//   src/include/intc_regs.sv, ID "INTC", VERSION and DATE at 0x00-0x08, the
//   registers from 0x10) and the logic intc (u_core, src/intc.sv), joined by
//   the register interface intc_regs_if (u_regs_if). Generated by
//   ip/scripts/regmap_gen.py from intc_regs.json and the ports of intc:
//   regenerate after changing either. Clock - aclk. Reset - synchronous
//   active low aresetn.
// Date: 2026-10-20
module intc_top #(
  parameter int NUM_IRQ = 16
) (
  input  logic aclk,
  input  logic aresetn,
  // s_axil: axil_if.slave (ip/shared/src/interfaces/axil_if.sv), ADDR_W = 8
  axil_if.slave s_axil,
  input  logic [NUM_IRQ-1:0] irq_i,
  output logic irq_o
);
  // register interface between the register map and the logic
  intc_regs_if #(.NUM_IRQ(NUM_IRQ)) u_regs_if ();

  intc_regs #(
    .NUM_IRQ(NUM_IRQ)
  ) u_regs (
    .aclk,
    .aresetn,
    .s_axil(s_axil),
    .r(u_regs_if)
  );
  intc #(
    .NUM_IRQ(NUM_IRQ)
  ) u_core (
    .aclk,
    .aresetn,
    .irq_i,
    .irq_o,
    .regs(u_regs_if)
  );
endmodule
